def choose_move(observation):
    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def nearest(points, sx, sy):
        best = None
        best_d = None
        for p in points or []:
            if not isinstance(p, (list, tuple)) or len(p) < 2:
                continue
            x, y = p[0], p[1]
            d = abs(x - sx) + abs(y - sy)
            if best_d is None or d < best_d:
                best_d = d
                best = (x, y)
        return best

    def step_toward(tx, ty, sx, sy):
        return [sign(tx - sx), sign(ty - sy)]

    def step_away(tx, ty, sx, sy):
        return [-sign(tx - sx), -sign(ty - sy)]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            tx, ty = ox, oy
            if (tx, ty) == (sx, sy):
                return [0, 0]
            return step_toward(tx, ty, sx, sy)
        w = observation.get("grid_width", 0)
        h = observation.get("grid_height", 0)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = None
        best_d = None
        for cx, cy in corners:
            d = abs(cx - ox) + abs(cy - oy)
            if best_d is None or d > best_d:
                best_d = d
                target = (cx, cy)
        if target is None:
            return step_away(ox, oy, sx, sy)
        return step_toward(target[0], target[1], sx, sy)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        target = nearest(targets, sx, sy)
        if target is None:
            ox2, oy2 = pos(observation.get("opponent_position"), (sx, sy))
            return step_away(ox2, oy2, sx, sy)
        return step_toward(target[0], target[1], sx, sy)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    target = nearest(resources, sx, sy)
    if target is not None:
        return step_toward(target[0], target[1], sx, sy)

    # Fallback: move away from opponent if close, otherwise hold or drift toward center.
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)
    if w and h:
        cx, cy = w // 2, h // 2
        if abs(ox - sx) + abs(oy - sy) <= 2:
            return step_away(ox, oy, sx, sy)
        return step_toward(cx, cy, sx, sy)

    return [0, 0]

